        static string English(string text){if(!englishUi)return text;var values=new Dictionary<string,string>{{"完成","Done"},{"截图公式","Formula"},{"截图提取文字","Screen OCR"},{"截图公式（MathType）","Capture formula for MathType · Alt+Shift+S"},{"截图识别与公式","OCR and formulas"},{"公式预览","Formula preview"},{"原图","Original"},{"全部识别文字","All recognized text"},{"公式","Formula"},{"行内 LaTeX","Inline LaTeX"},{"独立 LaTeX","Display LaTeX"},{"纯文字","Plain text"},{"已复制","Copied"},{"核对后复制到 MathType，或继续修改 LaTeX。","Review, then copy to MathType or edit the LaTeX."},{"可复制 LaTeX；MathML 暂不支持此语法。","Copy as LaTeX; MathML does not support this syntax yet."},{"请核对原图；仍可复制 MathML 或 LaTeX。","Review the original; MathML and LaTeX are available."},{"公式预览暂不可用。","Formula preview is unavailable."},{"翻译","Translate"},{"粘贴","Paste"},{"清空","Clear"},{"原文","Source"},{"译文","Translation"},{"保存…","Save…"},{"截图翻译","Screen translate"},{"截图 OCR + TeX","Screen OCR + TeX"},{"打开图片…","Open image…"},{"翻译图片","Translate image"},{"截图提取文字 + 公式 TeX","Screen OCR + formula TeX"},{"识别后翻译","Translate after OCR"},{"自动划词翻译","Translate selection automatically"},{"结果文件夹","Results folder"},{"复制 API 连接","Copy API connection"},{"界面语言","Interface language"},{"退出","Exit"},{"就绪","Ready · Ctrl+Enter to translate · Alt+S to capture"},{"Alt+S 已被占用，可使用截图按钮。","Alt+S is unavailable. Use Screen translate."},{"图片翻译与文字提取","Image translation and text extraction"},{"截图识别 · 图片 + TeX","Screenshot OCR · Image + TeX"},{"TeX 代码 / 识别结果","TeX code / recognized result"},{"关闭","Close"},{"保存 TeX…","Save TeX…"},{"复制 TeX","Copy TeX"},{"正在识别…","Recognizing…"},{"未识别出内容","No content recognized"},{"识别完成","Recognition complete"},{"TeX 已生成","TeX generated"},{"提取文字","Extract text"},{"原图／译图","Original / translated"},{"复制图片","Copy image"},{"保存译图…","Save image…"},{"翻译图片可切换原图；提取文字可选择复制。","Translate the image or extract selectable text."},{"已取消","Canceled"},{"提取完成，可选择和复制文字。","Text extracted. Select and copy it."},{"正在识别并翻译图片…","Recognizing and translating the image…"},{"译图已完成，长译文附在图片下