        void CaptureOcr(bool formulaOnly){bool hide=ContainsFocus;try{if(hide)Hide();Rectangle area;using(var image=CaptureOverlay.Pick(null,out area)){if(hide)Show();if(image!=null){var result=new OcrResultWindow(image,ResultStore.Folder(root),English){Icon=Icon};result.Show(this);RecognizePhoto(image,"Screenshot / 截图",true,result,formulaOnly);}}}catch(Exception error){if(hide)Show();status.Text=error.Message;}}
        internal static byte[] PhotoBytes(Image original) {
            Guard.Check(original.Width>0&&original.Height>0&&(long)original.Width*original.Height<=100000000,"Photo exceeds 100 megapixels / 照片过大。");
            double scale=Math.Min(1,Math.Min(4096.0/Math.Max(original.Width,original.Height),Math.Sqrt(16000000.0/((long)original.Width*original.Height))));
            using(var image=new Bitmap(Math.Max(1,(int)Math.Round(original.Width*scale)),Math.Max(1,(int)Math.Round(original.Height*scale)),PixelFormat.Format24bppRgb)) {
                using(var graphics=Graphics.FromImage(image)){graphics.Clear(Color.White);graphics.InterpolationMode=InterpolationMode.HighQualityBicubic;graphics.DrawImage(original,new Rectangle(Point.Empty,image.Size));}
                if(Array.IndexOf(original.PropertyIdList,0x112)>=0){int orientation=BitConverter.ToUInt16(original.GetPropertyItem(0x112).Value,0);RotateFlipType rotation=RotateFlipType.RotateNoneFlipNone;switch(orientation){case 2:rotation=RotateFlipType.RotateNoneFlipX;break;case 3:rotation=RotateFlipType.Rotate180FlipNone;break;case 4:rotation=RotateFlipType.Rotate180FlipX;break;case 5:rotation=RotateFlipType.Rotate90FlipX;break;case 6:rotation=RotateFlipType.Rotate90FlipNone;break;case 7:rotation=RotateFlipType.Rotate270FlipX;break;case 8:rotation=RotateFlipType.Rotate270FlipNone;break;}image.RotateFlip(rotation);}
                using(var stream=new MemoryStream()){image.Save(stream,ImageFormat.Png);if(stream.Length<=17*1024*1024)return stream.ToArray();}
                var encoder=ImageCodecInfo.GetImageEncoders().First(x=>x.FormatID==ImageFormat.Jpeg.Guid);
                foreach(long quality in new long[]{92,80,65})using(var stream=new MemoryStream())using(var parameters=new EncoderParameters(1)){parameters.Param[0]=new EncoderParameter(System.Drawing.Imaging.Encoder.Quality,quality);image.Save(stream,encoder,parameters);if(stream.Length<=17*1024*1024)return stream.ToArray();}
                throw new IOException("Photo is too complex; crop a smaller region / 请截取较小的照片区域。");
            }
        }
        void RecognizePhoto(Image image,string label){RecognizePhoto(image,label,false,null);}
        void RecognizePhoto(Image image,string label,bool formulas){RecognizePhoto(image,label,formulas,null);}
        void RecognizePhoto(Image image,string label,bool formulas,OcrResultWindow resultWindow,bool formulaOnly=false) {
            byte[] bytes=PhotoBytes(image);Cancel();activeOcr=resultWindow;if(resultWindow!=null){resultWindow.SetRecognizing();int operation=generation;resultWindow.FormClosed+=delegate{if(operation==Volatile.Read(ref generation)&&!translate.Enabled)Cancel();};}if(photo!=null)photo.Dispose();using(var stream=new MemoryStream(bytes))using(var loaded=Image.FromStream(stream))photo=new Bitmap(loaded);photoLines=null;int serial=Volatile.Read(ref generation);string mode=quality.SelectedIndex==1?"quality":"fast";translate.Enabled=false;cancel.Enabled=true;status.Text=English("正在识别…");
            new Thread(delegate(){try{var data=Request("/v1/ocr",new{image_base64=Convert.ToBase64String(bytes),mode=mode,formula=formulas,formula_only=formulaOnly},delegate{return serial!=Volatile.Read(ref generation);});string text=Json.Get(data,"text");Post(serial,delegate{photoLines=ImageLines(data);photoMode=Json.Get(data,"mode","quality");input.Text=text;output.Clear();translate.Enabled=true;cancel.Enabled=false;var formulasFound=new List<string>();foreach(Dictionary<string,object> line in (IList)data["lines"])if(Json.Get(line,"kind")=="formula")formulasFound.Add(Json.Get(line,"tex"));bool hasFormula=formulasFound.Count>0;status.Text=String.IsNullOrWhiteSpace(text)?English("未识别出文字，请换图或重新框选。"):English("已识别，可编辑、复制或翻译。");if(hasFormula)status.Text+=" · "+English("公式已转为 TeX");if(!String.IsNullOrWhiteSpace(text))status.Text+=Keep("ocr","","",text);if(resultWindow!=null)resultWindow.SetResult(text,formulasFound);activeOcr=null;if(autoTranslate.Checked&&!String.IsNullOrWhiteSpace(text))StartTranslation();});}catch(OperationCanceledException){Post(serial,delegate{if(resultWindow!=null)resultWindow.SetError(English("已取消"));translate.Enabled=true;cancel.Enabled=false;});}catch(Exception error){Post(serial,delegate{status.Text=error.Message;translate.Enabled=true;cancel.Enabled=false;if(resultWindow!=null)resultWindow.SetError(error.Message);});}}){IsBackground=true,Name="MiniAI photo OCR"}.Start();
        }
        void SaveText(){using(var dialog=new SaveFileDialog{Filter="UTF-8 text / 文本|*.txt",FileName="OCR.txt",InitialDirectory=ResultStore.Folder(root),DefaultExt="txt",AddExtension=true,RestoreDirectory=true})if(dialog.ShowDialog(this)==DialogResult.OK)try{File.WriteAllText(dialog.FileName,input.Text,new System.Text.UTF8Encoding(false));}catch(Exception error){status.Text=error.Message;}}
        protected override void Dispose(bool disposing){if(disposing){Cancel();options.Dispose();autoTranslate.Dispose();if(hotkey!=null)hotkey.Dispose();if(bubble!=null)bubble.Dispose();if(photo!=null)photo.Dispose();}base.Dispose(disposing);if(disposing&&applicationIcon!=null)applicationIcon.Dispose();}
    }
